<?php
/* ==========================================================================
   SINGERS PAGE (singers.php)  - PHP + database
   --------------------------------------------------------------------------
   Hero spotlight titles / images  -> songs   (section = 'spot')
   12 rotating hero singers        -> artists (section = 'singer')
   9 "Featured Artists" cards      -> artists (section = 'feature')
   29 "Full Lineup" artists        -> artists (section = 'lineup')

   Every list falls back to the original hard-coded data when the table is
   empty or MySQL is down, so the page never looks different.
   ========================================================================== */
require_once __DIR__ . '/includes/content.php';
require_once __DIR__ . '/includes/singers-data.php';

$currentPage = 'singers';
$pageTitle   = 'Singers | Audio Fire';

/* the 9 featured cards exactly as they were hard-coded (heights are visual) */
$AF_FEATURE_FALLBACK = [
    ['AYAAN RAZA',    'POWERHOUSE VOCALIST', 'uploads/singers/fcard-0.webp', 132, '#ff5fa2'],
    ['NOOR FATIMA',   'GLOBAL SUPERSTAR',    'uploads/singers/fcard-1.webp', 150, '#9ec81f'],
    ['DANISH QURESHI','MELODY MAKER',        'uploads/singers/fcard-2.webp', 150, '#ff8a1f'],
    ['ZARA KHAN',     'HIP-HOP ICON',        'uploads/singers/fcard-3.webp', 150, '#4d86ad'],
    ['ROHAN MEHRA',   'R&B LEGEND',          'uploads/singers/fcard-4.webp', 127, '#8d5cf0'],
    ['SANA REHMAN',   'POP SENSATION',       'uploads/singers/fcard-5.webp', 150, '#13b5a3'],
    ['KABIR SETHI',   'SOUL & BLUES',        'uploads/singers/fcard-6.webp', 150, '#e23a4e'],
    ['MAYA SIDDIQUI', 'CHART TOPPER',        'uploads/singers/fcard-7.webp', 148, '#e8b21d'],
    ['IMRAN DAR',     'LIVE PERFORMER',      'uploads/singers/fcard-8.webp', 150, '#3fb6e8'],
];

/* ---- small helpers ------------------------------------------------------ */
if (!function_exists('af_singer_int_list')) {
    function af_singer_int_list($csv)
    {
        $out = [];
        foreach (explode(',', (string) $csv) as $v) {
            $v = trim($v);
            if ($v !== '' && is_numeric($v)) { $out[] = (int) $v; }
        }
        return $out;
    }
}
if (!function_exists('af_singer_slug')) {
    function af_singer_slug($text)
    {
        $s = strtolower(trim((string) $text));
        $s = preg_replace('/[^a-z0-9]+/', '-', $s);
        return trim($s, '-') ?: 'artist';
    }
}

/* ---- 1. spotlight (16 titles + images) --------------------------------- */
/* the page always indexes PO[q] / TT[q] with q = 0..15, so both arrays are
   padded by cycling - a short table must never leave a hole in the hero */
$spotTitles = [];
$spotImages = [];
$spotDefault = [];
for ($i = 0; $i < 16; $i++) {
    $spotDefault[] = 'uploads/singers/hero-' . $i . '.webp';
}
foreach (af_songs('spot') as $s) {
    $t = trim((string) $s['title']);
    $i = (string) ($s['thumb'] ?: '');
    if ($t !== '' || $i !== '') { $spotTitles[] = $t; $spotImages[] = $i; }
}
$spotImages = array_values(array_filter($spotImages));
if (!$spotImages) {
    $spotImages = $spotDefault;
} else {
    $n = count($spotImages);
    while (count($spotImages) < 16) {
        $spotImages[] = $spotImages[count($spotImages) % $n] ?: $spotDefault[count($spotImages) % 16];
    }
}
if ($spotTitles) {
    $n = count($spotTitles);
    while (count($spotTitles) < 16) { $spotTitles[] = $spotTitles[count($spotTitles) % $n]; }
} else {
    $spotTitles = [];
}

/* ---- 2. the 12 rotating hero singers ----------------------------------- */
$heroSingers = [];
$heroImages  = [];
foreach (af_artists('singer') as $a) {
    $heroSingers[] = [
        'n'  => (string) $a['name'],
        'c'  => (string) ($a['accent'] ?: '#2E86C1'),
        'g'  => (string) ($a['genre'] ?: ''),
        'tg' => (string) ($a['tagline'] ?: ''),
        'd'  => (string) ($a['description'] ?: ''),
        'b'  => (string) ($a['birth'] ?: ''),
        'p'  => (string) ($a['place'] ?: ''),
        'db' => (int) ($a['debut'] ?: 0),
        'lb' => (string) ($a['label'] ?: ''),
        'y'  => af_singer_int_list($a['years']),
    ];
    $heroImages[] = (string) ($a['image'] ?: '');
}
/* IMG[i] must line up with S[i] - only hand the pair over when every one of
   the 12 has a picture, otherwise the original A / B arrays stay in charge */
$afHeroSingers = null;
$afHeroImages  = null;
if (count($heroSingers) === 12
    && count($heroImages) === 12
    && count(array_filter($heroImages)) === 12
) {
    $afHeroSingers = $heroSingers;
    $afHeroImages  = $heroImages;
}

/* ---- 3. featured cards -------------------------------------------------- */
$featureCards = [];
foreach (af_artists('feature') as $i => $a) {
    $featureCards[] = [
        'id'     => af_singer_slug($a['name']),
        'name'   => (string) $a['name'],
        'role'   => (string) ($a['role'] ?: $a['tagline'] ?: ''),
        'image'  => (string) ($a['image'] ?: ''),
        'height' => [132,150,150,150,127,150,150,148,150][$i % 9],
        'accent' => (string) ($a['accent'] ?: '#2E86C1'),
    ];
}
if (!$featureCards) {
    foreach ($AF_FEATURE_FALLBACK as $f) {
        $featureCards[] = [
            'id' => af_singer_slug($f[0]), 'name' => $f[0], 'role' => $f[1],
            'image' => $f[2], 'height' => $f[3], 'accent' => $f[4],
        ];
    }
}

/* ---- 4. the full lineup (29) -------------------------------------------- */
/* Read from the shared lineup data source (includes/singers-data.php) */
$afLineup = af_get_lineup_singers();

/* ---- values handed to the page script (null = use the JS fallback) ------ */
$afSpotTitles = $spotTitles ? json_encode($spotTitles, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES | JSON_HEX_TAG) : 'null';
$afSpotImages = json_encode($spotImages, JSON_UNESCAPED_SLASHES | JSON_HEX_TAG);
$afHeroImgJs  = $afHeroImages ? json_encode($afHeroImages, JSON_UNESCAPED_SLASHES | JSON_HEX_TAG) : 'null';
$afHeroSJs    = $afHeroSingers ? json_encode($afHeroSingers, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES | JSON_HEX_TAG) : 'null';
$afLineupJs   = $afLineup ? json_encode($afLineup, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES | JSON_HEX_TAG) : 'null';
?>
