  }
  .fcard:hover {
    transform: translateY(-4px);
    box-shadow:
      0 0 0 1px rgba(20,32,60,.08),
      0 22px 44px -12px rgba(30,45,80,.24),
      inset 0 1px 0 rgba(255,255,255,1);
  }
  .fcard:focus-visible { outline: 3px solid #0a84ff; outline-offset: 4px; }

  /* the photo box is clipped at the card's bottom edge only, so heads rise above the glass */
  .fphoto {
    position: absolute;
    left: 0; bottom: 0;
    width: 50%;
    height: var(--h);
    clip-path: inset(-60px -40px 0 0 round 0 0 0 var(--radius));
    pointer-events: none;
  }
  .fphoto img {
    position: absolute;
    left: 0; bottom: 0;
    width: 100%; height: 100%;
    object-fit: contain;
    object-position: left bottom;
    display: block;
  }

  .finfo {
    position: absolute;
    top: 0; bottom: 0; right: 0;
