.on[data-fx=wipe] .A{clip-path:inset(0)}.on[data-fx=ripple] .A{clip-path:circle(150% at var(--o))}.on[data-fx=morph] .A{clip-path:inset(0 round 0)}
[data-fx=parallax] .A{clip-path:var(--hi);filter:blur(2px)}[data-fx=parallax] .A .pi{transform:translate3d(calc(var(--vx)*24%),calc(var(--vy)*24%),0) scale(1.07)}
.on[data-fx=parallax] .A{clip-path:inset(0);filter:none}.on[data-fx=parallax] .A .pi{transform:none}
.on[data-fx=parallax] .B{transform:translate3d(calc(var(--vx)*-12%),calc(var(--vy)*-12%),0) scale(1.045);filter:brightness(.78) saturate(.75)}
[data-fx=curtain] .A,[data-fx=diagonal] .A{opacity:0;filter:blur(3px);transform:scale(.965)}
.on[data-fx=curtain] .A,.on[data-fx=diagonal] .A{opacity:1;filter:none;transform:none}
.b1{clip-path:var(--c1)}.b2{clip-path:var(--c2)}
.on .b1{transform:var(--m1);filter:blur(1px)}.on .b2{transform:var(--m2);filter:blur(1px)}
[data-fx=slide] .A{opacity:0;filter:blur(3px);transform:translate3d(calc(var(--vx)*16%),calc(var(--vy)*16%),0) scale(.985)}
.on[data-fx=slide] .A{opacity:1;filter:none;transform:none}
