.A.s{clip-path:var(--ci);opacity:0;filter:blur(1.5px);transform:translate3d(var(--ox),var(--oy),0);transition-property:transform,opacity,filter;transition-duration:calc(var(--d)*.85);transition-delay:var(--dr)}
.on .A.s{opacity:1;filter:none;transform:none;transition-delay:var(--dl)}
#ov{position:fixed;inset:0;z-index:50;display:none;place-items:center;padding:16px;background:rgba(4,6,10,.5);backdrop-filter:blur(10px);-webkit-backdrop-filter:blur(10px);opacity:0;transition:opacity .45s}
