/* ===== page glue: texture background, theme, glitch ===== */
@property --t-a{syntax:'<color>';inherits:true;initial-value:#ff5fa2}
:root{--t-a:#ff5fa2;--t-soft:color-mix(in srgb,var(--t-a) 55%,#fff);--t-light:color-mix(in srgb,var(--t-a) 48%,#0b0812);--t-mid:color-mix(in srgb,var(--t-a) 30%,#0b0812);--t-deep:color-mix(in srgb,var(--t-a) 10%,#050309);transition:--t-a .9s ease}
html{background:#050309;scroll-behavior:smooth}
body{margin:0;background:transparent;color:#fff;font-family:Montserrat,Inter,Arial,sans-serif;overflow-x:clip}
.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}
/* one shared texture layer behind the whole page */
#bg{position:fixed;inset:-14px;z-index:-1;isolation:isolate;pointer-events:none;background:radial-gradient(ellipse at 50% 45%,var(--t-light) 0%,var(--t-mid) 40%,var(--t-deep) 78%)}
#bg .tx{position:absolute;inset:0;background:url(data:image/jpeg;base64,) center/cover no-repeat;filter:grayscale(1) contrast(1.35) brightness(2.6);mix-blend-mode:soft-light;opacity:.85}
#bg .vg{position:absolute;inset:0;background:radial-gradient(ellipse at 50% 45%,transparent 42%,rgba(0,0,0,.6) 100%)}
#bg .gn{position:absolute;inset:0;opacity:.06;background:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='180' height='180'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='2' stitchTiles='stitch'/></filter><rect width='100%' height='100%' filter='url(%23n)'/></svg>")}
/* hero wrapper: fades softly into the page texture */
#hero{position:relative;height:100vh;height:100svh;min-height:620px}
#st{height:100%;-webkit-mask-image:linear-gradient(#000 calc(100% - 110px),transparent);mask-image:linear-gradient(#000 calc(100% - 110px),transparent)}
.ctl{transition:opacity .4s}.ctl.off{opacity:0;pointer-events:none}
@media(max-width:900px){#hero{height:auto;min-height:0}#st{height:auto;min-height:100svh;-webkit-mask-image:linear-gradient(#000 calc(100% - 70px),transparent);mask-image:linear-gradient(#000 calc(100% - 70px),transparent)}}
/* featured artists: dark transparent glass tinted by the hero theme */
#featured{position:relative;padding:clamp(70px,8vw,110px) clamp(16px,3vw,32px) 24px}
#featured::before,#singers::before{content:"";position:absolute;inset:0;pointer-events:none;z-index:0;
 background:radial-gradient(45% 30% at 22% 25%,color-mix(in srgb,var(--t-a) 30%,transparent),transparent 70%),radial-gradient(45% 30% at 80% 70%,color-mix(in srgb,var(--t-a) 24%,transparent),transparent 70%)}
#featured .fa{position:relative;z-index:1}
#featured .fcard{background:linear-gradient(160deg,rgba(255,255,255,.15),rgba(255,255,255,.04)),rgba(10,8,20,.2);border:1px solid rgba(255,255,255,.2);
 -webkit-backdrop-filter:blur(18px) saturate(150%);backdrop-filter:blur(18px) saturate(150%);
 box-shadow:inset 0 1px 0 rgba(255,255,255,.28),0 18px 40px rgba(0,0,0,.38);transition:transform .35s cubic-bezier(.2,.8,.2,1),box-shadow .35s,border-color .35s}
#featured .fcard:hover{transform:translateY(-6px);border-color:var(--t-soft);box-shadow:inset 0 1px 0 rgba(255,255,255,.35),0 24px 48px rgba(0,0,0,.45),0 0 44px color-mix(in srgb,var(--t-a) 38%,transparent)}
#featured .fname{color:#fff;font-family:Montserrat,sans-serif;font-weight:600}
#featured .frole{color:var(--t-soft);font-family:Montserrat,sans-serif;letter-spacing:.16em;font-size:clamp(10px,1vw,12.5px)}
#featured .fcard:focus-visible{outline:2px solid var(--t-soft);outline-offset:4px}
/* featured singers */
#singers{position:relative;padding:48px clamp(14px,4vw,56px) calc(70px + env(safe-area-inset-bottom,0px))}
#singers .sgrid{position:relative;z-index:1}
#singers .cd.on{border-color:var(--t-soft)}
#singers .cell{animation:none}
.pre{opacity:0;transform:translateY(30px) scale(.97)}
.rv{transition:opacity .9s cubic-bezier(.2,.8,.2,1),transform .9s cubic-bezier(.2,.8,.2,1)!important}
/* theme change: short glitch on the page texture and the cards */
@keyframes pgj{0%,100%{transform:none;filter:none}14%{transform:translate(-8px,0) skewX(1.4deg);filter:hue-rotate(28deg) saturate(1.6) brightness(1.15)}
 34%{transform:translate(7px,2px);filter:hue-rotate(-24deg) brightness(.8)}56%{transform:translate(-4px,-2px) skewX(-1deg);filter:saturate(1.8)}78%{transform:translate(3px,0);filter:brightness(1.2)}}
@keyframes cdj{0%,100%{filter:none}25%{transform:translateX(-4px) skewX(2deg);filter:drop-shadow(3px 0 #f0f) drop-shadow(-3px 0 #0ff)}55%{transform:translateX(4px);opacity:.82}80%{transform:translateX(-2px);filter:drop-shadow(-2px 0 #f0f) drop-shadow(2px 0 #0ff)}}
body.pg-gl #bg{animation:pgj .5s steps(7)}
body.pg-gl #featured .fcard,body.pg-gl #singers .cell{animation:cdj .45s steps(6)}
@media(prefers-reduced-motion:reduce){body.pg-gl #bg,body.pg-gl #featured .fcard,body.pg-gl #singers .cell{animation:none}:root{transition:none}}

/* section headings: same look as the home page (heavy Playfair, filled line + outlined line) */
